import{_ as a,o as t,c as r,ae as o}from"./chunks/framework.YL6nI5ZP.js";const m=JSON.parse('{"title":"Documentación de LocalSWMM","description":"","frontmatter":{},"headers":[],"relativePath":"es/index.md","filePath":"es/index.md"}'),i={name:"es/index.md"};function n(l,e,d,s,c,u){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="documentacion-de-localswmm" tabindex="-1">Documentación de LocalSWMM <a class="header-anchor" href="#documentacion-de-localswmm" aria-label="Permalink to &quot;Documentación de LocalSWMM&quot;">​</a></h1><p>Local SWMM es una aplicación web para modelado y simulación hidráulica 1D+2D de redes de alcantarillado pluvial y sanitario. El motor (HydroCouple OpenSWMM, compilado a WebAssembly) corre completamente en el navegador.</p><p>Esta documentación está organizada con <a href="https://diataxis.fr/" target="_blank" rel="noreferrer">Diátaxis</a>, que divide la documentación según la necesidad del usuario en cuatro cuadrantes:</p><table tabindex="0"><thead><tr><th>Cuadrante</th><th>Responde</th><th>Léelo cuando</th></tr></thead><tbody><tr><td><a href="./tutorials/">Tutoriales</a></td><td>aprender</td><td>Quieres aprender a construir y simular redes, paso a paso, desde cero.</td></tr><tr><td><a href="./how-to/">Guías de cómo hacer</a></td><td>hacer</td><td>Quieres completar una tarea concreta: ejecutar la app, configurarla, compilar desde fuente, desplegar, resolver un problema.</td></tr><tr><td><a href="./reference/">Referencia</a></td><td>conocer</td><td>Necesitas un dato exacto: formatos de datos, opciones del motor, glosario.</td></tr><tr><td><a href="./explanation/">Explicación</a></td><td>comprender</td><td>Quieres entender <em>cómo y por qué</em> el motor calcula lo que calcula: arquitectura, hidráulica 1D, acoplamiento 2D, modificaciones del motor.</td></tr></tbody></table><h2 id="orientacion" tabindex="-1">Orientación <a class="header-anchor" href="#orientacion" aria-label="Permalink to &quot;Orientación&quot;">​</a></h2><ul><li><strong>¿Nuevo en LocalSWMM?</strong> Parte por los <a href="./tutorials/">tutoriales</a> — enseñan haciendo.</li><li><strong>¿Tienes una tarea específica?</strong> Ve directo a las <a href="./how-to/">guías de cómo hacer</a>.</li><li><strong>¿Necesitas un dato?</strong> Búscalo en la <a href="./reference/">referencia</a>.</li><li><strong>¿Quieres entender las matemáticas o la arquitectura?</strong> Lee la <a href="./explanation/">explicación</a>.</li></ul><h2 id="idiomas" tabindex="-1">Idiomas <a class="header-anchor" href="#idiomas" aria-label="Permalink to &quot;Idiomas&quot;">​</a></h2><ul><li><a href="/docs/es/">Español</a> (primario para este sitio)</li><li><a href="/docs/">English</a> — English is the primary content language; Spanish mirrors it where translated.</li></ul><h2 id="fuentes" tabindex="-1">Fuentes <a class="header-anchor" href="#fuentes" aria-label="Permalink to &quot;Fuentes&quot;">​</a></h2><p>Los documentos fuente originales (LaTeX/HTML) desde los cuales se convirtió parte de esta documentación se conservan en <a href="./../sources/">sources/</a>.</p><h2 id="relacionados" tabindex="-1">Relacionados <a class="header-anchor" href="#relacionados" aria-label="Permalink to &quot;Relacionados&quot;">​</a></h2><ul><li><a href="https://github.com/JoaquinAlvarado-py/LocalSWMM" target="_blank" rel="noreferrer">README del repositorio</a> — visión general del proyecto y inicio rápido</li><li><a href="https://github.com/JoaquinAlvarado-py/LocalSWMM/blob/experimental/CONTEXT.md" target="_blank" rel="noreferrer">CONTEXT.md</a> — glosario de dominio y terminología (Español)</li></ul>',12)])])}const p=a(i,[["render",n]]);export{m as __pageData,p as default};
